void loadMap(){std::fill(map_.begin(),map_.end(),MapCell{});mapObjects_.clear();mapBuildings_.clear();mapUnits_.clear();std::ifstream in("maps/editor_map.txt");if(!in)return;std::string tag;int ver,w,h;if(!(in>>tag>>ver>>w>>h)||tag!="CCMAP")return;if(ver<4){int x,y,s,sx,sy,t=16;while(in>>x>>y>>s>>sx>>sy){if(ver>=3){if(!(in>>t))break;}else t=16;if(x>=0&&x<MapW&&y>=0&&y<MapH&&s>=0&&s<(int)Sheet::Count)map_[y*MapW+x]={s,sx,sy,t};}return;}char type;while(in>>type){if(type=='T'){int x,y,s,sx,sy,t;if(in>>x>>y>>s>>sx>>sy>>t&&x>=0&&x<MapW&&y>=0&&y<MapH&&s>=0&&s<(int)Sheet::Count)map_[y*MapW+x]={s,sx,sy,t};}else if(type=='O'){MapObject p;if(in>>p.x>>p.y>>p.sheet>>p.sx>>p.sy>>p.tile&&p.sheet>=0&&p.sheet<(int)Sheet::Count)mapObjects_.push_back(p);}else if(type=='B'){int k;MapBuilding p;if(in>>k>>p.team>>p.x>>p.y&&k>=0&&k<=6){p.kind=(BuildingKind)k;p.team=std::max(0,std::min(p.team,1));mapBuildings_.push_back(p);}}else if(type=='U'){int k;MapUnit p;if(in>>k>>p.team>>p.x>>p.y&&k>=0&&k<=6){p.kind=(UnitKind)k;p.team=std::max(0,std::min(p.team,1));mapUnits_.push_back(p);}}else{std::string line;std::getline(in,line);}}}
