void updateEditor(ra::Engine&e,float dt){editorAnim_+=dt;float panel=430,w=e.windowWidth(),h=e.windowHeight(),mx=e.mouseX(),my=e.mouseY(),px=w-panel+14;auto ss=editorSheets();if(editorSheet_>=(int)ss.size())editorSheet_=0;if(e.keyPressed(ra::Key::Escape)){screen_=Screen::Menu;e.setWindowTitle("Click Command");return;}if((editorTab_==EditorTab::Terrain||editorTab_==EditorTab::Objects)&&!ss.empty()){if(e.keyPressed(ra::Key::Q)){editorSheet_=(editorSheet_+(int)ss.size()-1)%(int)ss.size();editorSX_=editorSY_=0;editorPaletteScroll_=0;}if(e.keyPressed(ra::Key::E)){editorSheet_=(editorSheet_+1)%(int)ss.size();editorSX_=editorSY_=0;editorPaletteScroll_=0;}}
 float wheel=e.mouseWheelY();if(wheel!=0){if(mx>w-panel&&(editorTab_==EditorTab::Terrain||editorTab_==EditorTab::Objects)){editorPaletteScroll_=std::max(0,editorPaletteScroll_-(int)wheel);}else editorZoom_=clampf(editorZoom_+wheel*.15f,.5f,3);}float dx=0,dy=0;if(e.keyDown(ra::Key::A)||e.keyDown(ra::Key::Left))dx--;if(e.keyDown(ra::Key::D)||e.keyDown(ra::Key::Right))dx++;if(e.keyDown(ra::Key::W)||e.keyDown(ra::Key::Up))dy--;if(e.keyDown(ra::Key::S)||e.keyDown(ra::Key::Down))dy++;editorCamX_=clampf(editorCamX_+dx*500*dt/editorZoom_,0,std::max(0.0f,MapW*Tile-(w-panel)/editorZoom_));editorCamY_=clampf(editorCamY_+dy*500*dt/editorZoom_,0,std::max(0.0f,MapH*Tile-h/editorZoom_));
 if(e.mousePressed(ra::MouseButton::Left)&&mx>w-panel){for(int i=0;i<4;++i)if(click(e,px+i*98,54,92,30)){editorTab_=(EditorTab)i;editorSheet_=editorSX_=editorSY_=editorEntity_=editorPaletteScroll_=0;return;}if(click(e,px,90,86,28)){editorOwner_=1-editorOwner_;return;}if(editorTab_==EditorTab::Terrain||editorTab_==EditorTab::Objects){if(ss.empty())return;if(click(e,px+98,90,36,28)){editorSheet_=(editorSheet_+(int)ss.size()-1)%(int)ss.size();editorSX_=editorSY_=editorPaletteScroll_=0;return;}if(click(e,px+panel-64,90,36,28)){editorSheet_=(editorSheet_+1)%(int)ss.size();editorSX_=editorSY_=editorPaletteScroll_=0;return;}auto inf=ss[editorSheet_];const auto&t=tex(inf.id);int cols=std::max(1,t.width/inf.tile),rows=std::max(1,t.height/inf.tile);if(inf.rowLimit>0)rows=std::min(rows,inf.rowLimit);float cell=36,py=132;int c=(int)((mx-px)/cell),r=editorPaletteScroll_+(int)((my-py)/cell);if(c>=0&&c<cols&&r>=0&&r<rows&&my>=py&&my<h-190){editorSX_=c;editorSY_=r;return;}}else{float py=132,cellW=188,cellH=92;int c=(int)((mx-px)/cellW),r=(int)((my-py)/cellH),idx=r*2+c;int count=editorTab_==EditorTab::Buildings?7:7;if(c>=0&&c<2&&idx>=0&&idx<count&&my>=py&&my<h-190){editorEntity_=idx;return;}}if(click(e,px,h-142,110,32)){saveMap();return;}if(click(e,px+120,h-142,110,32)){loadMap();return;}if(click(e,px,h-98,panel-28,32)){std::fill(map_.begin(),map_.end(),MapCell{});mapObjects_.clear();mapBuildings_.clear();mapUnits_.clear();return;}if(click(e,px,h-54,panel-28,32)){screen_=Screen::Menu;return;}}
 if(mx<w-panel){float wx=editorCamX_+mx/editorZoom_,wy=editorCamY_+my/editorZoom_;int tx=(int)(wx/Tile),ty=(int)(wy/Tile);float sx=tx*Tile+Tile*.5f,sy=ty*Tile+Tile*.5f;if(tx<0||tx>=MapW||ty<0||ty>=MapH)return;if(e.mousePressed(ra::MouseButton::Right)){if(editorTab_==EditorTab::Terrain)map_[ty*MapW+tx]={};else if(editorTab_==EditorTab::Objects){mapObjects_.erase(std::remove_if(mapObjects_.begin(),mapObjects_.end(),[&](const MapObject&p){return std::abs(p.x-sx)<Tile*.6f&&std::abs(p.y-sy)<Tile*.6f;}),mapObjects_.end());}else if(editorTab_==EditorTab::Buildings){mapBuildings_.erase(std::remove_if(mapBuildings_.begin(),mapBuildings_.end(),[&](const MapBuilding&p){return std::abs(p.x-sx)<Tile*1.5f&&std::abs(p.y-sy)<Tile*1.5f;}),mapBuildings_.end());}else mapUnits_.erase(std::remove_if(mapUnits_.begin(),mapUnits_.end(),[&](const MapUnit&p){return std::abs(p.x-sx)<Tile*.7f&&std::abs(p.y-sy)<Tile*.7f;}),mapUnits_.end());return;}if(editorTab_==EditorTab::Terrain&&e.mouseDown(ra::MouseButton::Left)&&!ss.empty()){auto inf=ss[editorSheet_];map_[ty*MapW+tx]={(int)inf.id,editorSX_,editorSY_,inf.tile};}else if(editorTab_==EditorTab::Objects&&e.mousePressed(ra::MouseButton::Left)&&!ss.empty()){auto inf=ss[editorSheet_];mapObjects_.push_back({(int)inf.id,editorSX_,editorSY_,inf.tile,sx,sy});}else if(editorTab_==EditorTab::Buildings&&e.mousePressed(ra::MouseButton::Left)){mapBuildings_.push_back({(BuildingKind)std::max(0,std::min(editorEntity_,6)),editorOwner_,sx,sy});}else if(editorTab_==EditorTab::Units&&e.mousePressed(ra::MouseButton::Left)){mapUnits_.push_back({(UnitKind)std::max(0,std::min(editorEntity_,6)),editorOwner_,sx,sy});}}}
