$buildingArt = @'
void drawScreenTile(ra::Engine&e,const ra::Texture&t,ra::Rect src,float x,float y,float cell){if(t)e.drawTextureRegion(t,src,{x,y,cell,cell});}
void drawBuildingArt(ra::Engine&e,BuildingKind k,float cx,float cy,float scale){float c=16*scale;auto tile=[&](const ra::Texture&t,int sx,int sy,int x,int y){drawScreenTile(e,t,srcCell(sx,sy,16),cx+x*c,cy+y*c,c);};if(k==BuildingKind::Base){for(int y=-1;y<=1;++y)for(int x=-2;x<=1;++x)tile(wooden_,0,0,x,y);for(int x=-2;x<=1;++x)tile(walls_,1,0,x,-2);tile(walls_,0,1,-2,-1);tile(walls_,2,1,1,-1);tile(walls_,0,2,-2,0);tile(walls_,2,2,1,0);if(door_)tile(door_,0,0,0,1);else tile(walls_,1,3,0,1);tile(chest_,0,0,-1,0);}else if(k==BuildingKind::Barracks){for(int y=-1;y<=0;++y)for(int x=-1;x<=1;++x)tile(flooring_,0,0,x,y);for(int x=-1;x<=1;++x)tile(walls_,1,0,x,-2);tile(walls_,0,1,-1,-1);tile(walls_,2,1,1,-1);if(doorB_)tile(doorB_,0,0,0,0);else tile(walls_,1,3,0,0);}else if(k==BuildingKind::Hangar){for(int y=-1;y<=1;++y)for(int x=-2;x<=1;++x)tile(flooring_,1,1,x,y);for(int x=-2;x<=1;++x)tile(fences_,1,1,x,-2);tile(fences_,0,1,-2,-1);tile(fences_,2,1,1,-1);}else if(k==BuildingKind::Silo){for(int y=-1;y<=0;++y)for(int x=-1;x<=0;++x)tile(wooden_,0,0,x,y);tile(chest_,0,0,-1,-1);if(chest2_)tile(chest2_,0,0,0,-1);tile(chest_,0,0,-1,0);if(chest2_)tile(chest2_,0,0,0,0);}else if(k==BuildingKind::Crop){for(int y=-1;y<=1;++y)for(int x=-2;x<=1;++x){tile(plains_,4,0,x,y);tile(decor_,(x-y+8)%4,0,x,y);}}else if(k==BuildingKind::Academy){for(int y=-1;y<=1;++y)for(int x=-1;x<=1;++x)tile(carpet_?carpet_:flooring_,0,0,x,y);for(int x=-1;x<=1;++x)tile(walls_,1,0,x,-2);tile(walls_,0,1,-1,-1);tile(walls_,2,1,1,-1);if(door_)tile(door_,0,0,0,1);}else if(k==BuildingKind::Training){for(int x=-2;x<=1;++x){tile(fences_,1,1,x,-2);tile(fences_,1,1,x,1);}for(int y=-1;y<=0;++y){tile(fences_,0,1,-2,y);tile(fences_,2,1,1,y);}for(int y=-1;y<=0;++y)for(int x=-1;x<=0;++x)tile(plains_,4,0,x,y);}}
void drawUnitSprite(ra::Engine&e,UnitKind k,float x,float y,float size,int frame){if(k==UnitKind::Air){e.drawTextureRegion(slime_,frame32(frame%4,0),{x-size*.5f,y-size*.5f,size,size});return;}int row=0;switch(k){case UnitKind::Worker:row=0;break;case UnitKind::Guerrilla:row=1;break;case UnitKind::Soldier:row=2;break;case UnitKind::Infantry:row=3;break;case UnitKind::Sniper:row=4;break;case UnitKind::Cannoneer:if(skeleton_){e.drawTextureRegion(skeleton_,frame48(frame%6,0),{x-size*.5f,y-size*.65f,size,size});return;}row=5;break;default:break;}e.drawTextureRegion(player_,frame48(frame%6,row),{x-size*.5f,y-size*.68f,size,size});}
void drawBuilding(ra::Engine&e,const Building&b){float sx=(b.x-cameraX_)*zoom_,sy=(b.y-cameraY_)*zoom_;drawBuildingArt(e,b.kind,sx,sy,2.0f*zoom_);std::string n=buildingName(b.kind);if(b.buildLeft>0)n+=" BUILDING";if(b.kind==BuildingKind::Crop&&b.cropReady)n+=" READY";e.drawText(sx-42,sy-70*zoom_,n,b.team==0?ra::Color{220,240,255,255}:ra::Color{190,230,190,255});if(b.id==selectedBuilding_)e.drawRect({sx-60*zoom_,sy-55*zoom_,120*zoom_,110*zoom_},{255,220,70,255});}
'@
Replace-Section 'void drawBuilding(' 'void drawUnits(' $buildingArt 'building art'

$drawUnits = @'
void drawUnits(ra::Engine&e,float vw,float vh){int i=0;for(const auto&u:world_.units()){float x=(u.position.x-cameraX_)*zoom_,y=(u.position.y-cameraY_)*zoom_;UnitKind k=kinds_.count(u.id)?kinds_.at(u.id):UnitKind::Soldier;float s=(k==UnitKind::Air?58:(k==UnitKind::Worker?46:52))*zoom_;if(x<-s||y<-s||x>vw+s||y>vh+s){++i;continue;}if(u.selected)e.drawRect({x-s*.55f,y-s*.55f,s*1.1f,s*1.1f},{255,220,70,255});if(u.team==0)drawUnitSprite(e,k,x,y,s,(i+(int)u.aiStep)%6);else e.drawTextureRegion(slime_,frame32((i+(int)u.aiStep)%4,0),{x-s*.5f,y-s*.5f,s,s});++i;}}
'@
Replace-Section 'void drawUnits(' 'void drawHud(' $drawUnits 'unit visuals'

$action = @'
void drawAction(ra::Engine&e,float x,float y,int icon,const std::string&name,const std::string&cost,bool en){e.fillRect({x,y,92,92},en?ra::Color{32,69,38,255}:ra::Color{24,31,26,255});e.drawRect({x,y,92,92},en?ra::Color{105,151,109,255}:ra::Color{60,70,62,255});if(icon==0)drawUnitSprite(e,UnitKind::Worker,x+46,y+27,42,0);else if(icon==1)drawUnitSprite(e,UnitKind::Guerrilla,x+46,y+27,42,1);else if(icon>=2&&icon<=7)drawBuildingArt(e,(BuildingKind)(icon-1),x+46,y+29,.62f);else if(icon==8)drawUnitSprite(e,UnitKind::Soldier,x+46,y+27,42,2);else if(icon==9)drawUnitSprite(e,UnitKind::Infantry,x+46,y+27,42,3);else if(icon==10)drawUnitSprite(e,UnitKind::Sniper,x+46,y+27,42,4);else if(icon==11)drawUnitSprite(e,UnitKind::Cannoneer,x+46,y+27,42,1);else if(icon==12)drawUnitSprite(e,UnitKind::Air,x+46,y+27,42,1);e.drawText(x+5,y+53,name,en?ra::Color{240,239,214,255}:ra::Color{105,112,106,255});e.drawText(x+5,y+72,cost,en?ra::Color{255,214,80,255}:ra::Color{95,100,96,255});}
'@
Replace-Section 'void drawAction(' 'bool handleActions(' $action 'HUD action icons'

$renderGame = @'
void renderGame(ra::Engine&e){float vw=hudX(e),vh=e.windowHeight();e.clear({8,13,9,255});drawTerrain(e,vw,vh);for(const auto&o:mapObjects_){const auto&t=tex((Sheet)o.sheet);float x=(o.x-cameraX_)*zoom_,y=(o.y-cameraY_)*zoom_,s=Tile*zoom_;if(t)e.drawTextureRegion(t,srcCell(o.sx,o.sy,o.tile),{x-s*.5f,y-s*.5f,s,s});}for(const auto&b:buildings_)drawBuilding(e,b);drawUnits(e,vw,vh);if(drag_){float l=std::min(sx_,ex_),r=std::max(sx_,ex_),t=std::min(sy_,ey_),b=std::max(sy_,ey_);e.drawRect({l,t,r-l,b-t},{96,238,104,255});}if(pending_!=BuildingKind::None)e.drawText(16,16,std::string("PLACE ")+buildingName(pending_)+" - RMB CANCEL",{255,220,90,255});for(auto&f:fx_)e.drawText(f.x-4,f.y,"+1",{255,220,70,255});drawHud(e,vw,vh);if(gameOver_){e.fillRect({vw*.5f-180,vh*.45f,360,90},{12,12,12,220});e.drawText(vw*.5f-30,vh*.49f,winner_==localTeam()?"VICTORY":"DEFEAT",{255,220,90,255});}}

'@
