$renderEditor = @'
const char* unitName(UnitKind k)const{switch(k){case UnitKind::Worker:return"WORKER";case UnitKind::Guerrilla:return"GUERRILLA";case UnitKind::Soldier:return"SOLDIER";case UnitKind::Infantry:return"INFANTRY";case UnitKind::Sniper:return"SNIPER";case UnitKind::Cannoneer:return"CANNONEER";case UnitKind::Air:return"AIR UNIT";}return"UNIT";}
void renderEditor(ra::Engine&e){float panel=430,w=e.windowWidth(),h=e.windowHeight(),canvas=w-panel;e.clear({8,13,9,255});int fx=std::max(0,(int)(editorCamX_/Tile)-1),fy=std::max(0,(int)(editorCamY_/Tile)-1),lx=std::min(MapW-1,fx+(int)(canvas/(Tile*editorZoom_))+3),ly=std::min(MapH-1,fy+(int)(h/(Tile*editorZoom_))+3);for(int y=fy;y<=ly;++y)for(int x=fx;x<=lx;++x){float s=Tile*editorZoom_,dx=(x*Tile-editorCamX_)*editorZoom_,dy=(y*Tile-editorCamY_)*editorZoom_;drawMapCell(e,x,y,dx,dy,s);e.drawRect({dx,dy,s,s},{28,45,30,55});}for(const auto&o:mapObjects_){const auto&t=tex((Sheet)o.sheet);float x=(o.x-editorCamX_)*editorZoom_,y=(o.y-editorCamY_)*editorZoom_,s=Tile*editorZoom_;if(t)e.drawTextureRegion(t,srcCell(o.sx,o.sy,o.tile),{x-s*.5f,y-s*.5f,s,s});}for(const auto&p:mapBuildings_){float x=(p.x-editorCamX_)*editorZoom_,y=(p.y-editorCamY_)*editorZoom_;drawBuildingArt(e,p.kind,x,y,2.0f*editorZoom_);e.drawText(x-18,y-56*editorZoom_,p.team==0?"P1":"P2",p.team==0?ra::Color{220,240,255,255}:ra::Color{255,185,185,255});}int af=(int)(editorAnim_*7)%6;for(const auto&p:mapUnits_){float x=(p.x-editorCamX_)*editorZoom_,y=(p.y-editorCamY_)*editorZoom_;drawUnitSprite(e,p.kind,x,y,46*editorZoom_,af);e.drawText(x-8,y-31*editorZoom_,p.team==0?"P1":"P2",p.team==0?ra::Color{220,240,255,255}:ra::Color{255,185,185,255});}
 e.fillRect({canvas,0,panel,h},{12,18,14,255});float px=canvas+14;e.drawText(px,16,"MAP EDITOR - MYSTIC WOODS",{245,238,205,255});e.drawText(px,34,"TILES / OBJECTS / BUILDINGS / UNITS",{160,185,165,255});const char*tabs[]={"TERRAIN","OBJECTS","BUILDINGS","UNITS"};for(int i=0;i<4;++i){float x=px+i*98;e.fillRect({x,54,92,30},editorTab_==(EditorTab)i?ra::Color{55,100,57,255}:ra::Color{28,54,32,255});e.drawRect({x,54,92,30},{90,125,94,255});e.drawText(x+7,66,tabs[i],{240,239,214,255});}e.fillRect({px,90,86,28},{37,75,41,255});e.drawText(px+8,101,editorOwner_==0?"OWNER P1":"OWNER P2",{255,220,90,255});
 auto btn=[&](float x,float y,float ww,const char*s){e.fillRect({x,y,ww,32},{37,75,41,255});e.drawRect({x,y,ww,32},{105,140,110,255});e.drawText(x+10,y+12,s,{240,239,214,255});};if(editorTab_==EditorTab::Terrain||editorTab_==EditorTab::Objects){auto ss=editorSheets();if(!ss.empty()){if(editorSheet_>=(int)ss.size())editorSheet_=0;auto inf=ss[editorSheet_];const auto&t=tex(inf.id);btn(px+98,90,36,"<");e.drawText(px+142,101,inf.name,{255,220,90,255});btn(px+panel-64,90,36,">");int cols=std::max(1,t.width/inf.tile),rows=std::max(1,t.height/inf.tile);if(inf.rowLimit>0)rows=std::min(rows,inf.rowLimit);float cell=36,py=132;int visible=std::max(1,(int)((h-330)/cell));int maxScroll=std::max(0,rows-visible);editorPaletteScroll_=std::min(editorPaletteScroll_,maxScroll);int last=std::min(rows,editorPaletteScroll_+visible);for(int r=editorPaletteScroll_;r<last;++r)for(int c=0;c<cols;++c){float x=px+c*cell,y=py+(r-editorPaletteScroll_)*cell;if(x+cell>canvas+panel-12)continue;e.drawTextureRegion(t,srcCell(c,r,inf.tile),{x+2,y+2,32,32});e.drawRect({x,y,36,36},c==editorSX_&&r==editorSY_?ra::Color{255,220,70,255}:ra::Color{60,75,63,160});}e.drawText(px,h-184,"MOUSE WHEEL: SCROLL PALETTE",{145,170,150,255});}}else if(editorTab_==EditorTab::Buildings){for(int i=0;i<7;++i){int c=i%2,r=i/2;float x=px+c*188,y=132+r*92;e.fillRect({x,y,178,82},editorEntity_==i?ra::Color{37,76,42,255}:ra::Color{20,31,23,255});e.drawRect({x,y,178,82},editorEntity_==i?ra::Color{255,220,70,255}:ra::Color{70,90,73,255});drawBuildingArt(e,(BuildingKind)i,x+42,y+43,.72f);e.drawText(x+80,y+34,buildingName((BuildingKind)i),{240,239,214,255});}}else{for(int i=0;i<7;++i){int c=i%2,r=i/2;float x=px+c*188,y=132+r*92;e.fillRect({x,y,178,82},editorEntity_==i?ra::Color{37,76,42,255}:ra::Color{20,31,23,255});e.drawRect({x,y,178,82},editorEntity_==i?ra::Color{255,220,70,255}:ra::Color{70,90,73,255});drawUnitSprite(e,(UnitKind)i,x+40,y+42,50,af);e.drawText(x+78,y+34,unitName((UnitKind)i),{240,239,214,255});}}e.drawText(px,h-184,"LMB PLACE   RMB ERASE   WASD PAN",{145,170,150,255});btn(px,h-142,110,"SAVE");btn(px+120,h-142,110,"LOAD");btn(px,h-98,panel-28,"CLEAR MAP");btn(px,h-54,panel-28,"BACK TO MENU");}

